compile.workshop:
variables {
    global:
        0: g
}

//Optimizations disabled
rule ("macro body defined before the directive") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(1, ==, 1));
            Set Global Variable(g, 1);
        End;
    }
}

